// Pure roster validation. Do not persist a snapshot of people or credentials.
const text = (value) => String(value ?? '').trim();
const codeFromPrimaryLocation = (value) => text(value).match(/\(([^)]+)\)\s*$/)?.[1] ?? '';
const validEmail = (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);

function siteUrl(value) {
  const raw = text(value);
  if (!raw) return '';
  // n8n Code nodes don't consistently expose the URL constructor.
  const match = raw.match(/^(?:https:\/\/)?([a-z0-9.-]+)(\/[^?#\\\s]*)?$/i);
  if (!match) return '';
  const host = match[1].toLowerCase();
  const labels = host.split('.');
  if (labels.length < 2 || labels.some((label) => !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label))) return '';
  const path = match[2] || '/';
  return 'https://' + host + path.replace(/\/*$/, '/');
}

function buildCampaignRoster(locationRows, wordpressRows, dentistRows, testRows = []) {
  const heldLocations = new Set(['DFW-24', 'DFW-25']);
  const wordpressByCode = new Map();
  for (const [rawCode, rawName, rawUrl] of wordpressRows) {
    const code = text(rawCode);
    if (!code) continue;
    if (wordpressByCode.has(code)) throw new Error(`Duplicate WordPress location code: ${code}`);
    wordpressByCode.set(code, { name: text(rawName), url: siteUrl(rawUrl) });
  }

  const locations = [];
  const excludedLocations = [];
  const locationByCode = new Map();
  for (const [rawCode, rawName, rawType, rawPublicUrl] of locationRows) {
    const code = text(rawCode);
    if (!code) continue;
    if (locationByCode.has(code)) throw new Error(`Duplicate location code: ${code}`);
    const name = text(rawName);
    const wordpress = wordpressByCode.get(code);
    const publicUrl = siteUrl(rawPublicUrl);
    const reason = heldLocations.has(code) ? 'not_launched'
      : /-(E|O|P)$/i.test(code) || text(rawType) !== 'GD' ? 'specialty_or_nonpractice'
        : /test/i.test(`${code} ${name}`) ? 'test_location'
          : !publicUrl ? 'missing_or_invalid_public_website'
            : !wordpress?.url ? 'missing_or_invalid_wordpress_site'
              : wordpress.name !== name ? 'wordpress_name_mismatch' : null;
    if (reason) {
      excludedLocations.push({ code, name, reason });
      continue;
    }
    const location = { code, name, public_website_url: publicUrl, wordpress_site_url: wordpress.url };
    locationByCode.set(code, location);
    locations.push(location);
  }

  const doctors = [];
  const excludedDoctors = [];
  const seenEmails = new Set();
  for (const [rawName, rawPrimary, rawDepartment, rawEmployment, rawEmail] of dentistRows) {
    const name = text(rawName);
    if (!name) continue;
    const primary = text(rawPrimary);
    const code = codeFromPrimaryLocation(primary);
    const email = text(rawEmail).toLowerCase();
    const reason = text(rawDepartment) !== 'General Dentist' ? 'not_general_dentist'
      : !['Full-Time', 'Part-Time'].includes(text(rawEmployment)) ? 'not_employee'
        : /test/i.test(primary) || code === 'DFW-T' ? 'test_location'
          : !locationByCode.has(code) ? 'location_unavailable'
            : !validEmail(email) ? 'missing_or_invalid_work_email' : null;
    if (reason) {
      excludedDoctors.push({ name, code, reason });
      continue;
    }
    if (seenEmails.has(email)) throw new Error(`Duplicate work email in census: ${email}`);
    seenEmails.add(email);
    doctors.push({ name, email, location_code: code });
  }

  const testUsers = [];
  const seenTestEmails = new Set();
  for (const [rawEmail, rawName, rawLocation, rawWordpressUrl] of testRows) {
    const email = text(rawEmail).toLowerCase();
    if (!email) continue;
    const name = text(rawName);
    const location = text(rawLocation);
    const wordpressUrl = siteUrl(rawWordpressUrl);
    if (!validEmail(email) || !name || !location || !wordpressUrl) throw new Error(`Incomplete test user row: ${email}`);
    if (seenTestEmails.has(email)) throw new Error(`Duplicate test email: ${email}`);
    seenTestEmails.add(email);
    testUsers.push({ name, email, location_name: location, wordpress_site_url: wordpressUrl });
  }
  return { locations, doctors, testUsers, excludedLocations, excludedDoctors };
}

const rows = (nodeName, columns) => {
  const observed = $(nodeName).first().json.rows;
  if (!Array.isArray(observed)) throw new Error('Sheet read unavailable: ' + nodeName);
  return observed.map((row) => columns.map((column) => row[column] ?? ''));
};
const censusRows = $('Keep dentist rows together').first().json.rows;
const emailByRow = new Map($('Keep email rows together').first().json.rows.map((row) => [Number(row.row_number), row['Work Email'] ?? '']));
const dentists = censusRows.map((row) => {
  const rowNumber = Number(row.row_number);
  if (!Number.isInteger(rowNumber)) throw new Error('Doctor census row number missing.');
  return [row.Employee ?? '', row['Primary Location'] ?? '', row.Department ?? '', row['Employment Type'] ?? '', emailByRow.get(rowNumber) ?? ''];
});
const roster = buildCampaignRoster(
  rows('Keep location rows together', ['Code', 'Name', 'Type', 'URL']),
  rows('Keep website rows together', ['Codes', 'Locations', 'Wordpress Site']),
  dentists,
  $('Read test users').all().map((item) => ['Email', 'Name', 'Location', 'Wordpress URL'].map((column) => item.json[column] ?? ''))
);
const start = $('Start selection preview').first().json;
const audience = start.audience ?? start.Audience;
if (!['Test users only', 'General dentists (preview only)'].includes(audience)) throw new Error('Choose a valid audience.');
const testOnly = audience === 'Test users only';
if (testOnly && !roster.testUsers.length) throw new Error('The Test User tab has no complete entries.');
if (!testOnly && (!roster.locations.length || !roster.doctors.length)) throw new Error('No eligible general-dentist locations or doctors.');
const locationByName = new Map();
const testLocations = [];
for (const user of roster.testUsers) {
  const key = user.location_name + '|' + user.wordpress_site_url;
  if (!locationByName.has(user.location_name)) {
    const location = { code: 'TEST-' + (testLocations.length + 1), name: user.location_name, wordpress_site_url: user.wordpress_site_url };
    locationByName.set(user.location_name, location);
    testLocations.push(location);
  } else if (locationByName.get(user.location_name).wordpress_site_url !== user.wordpress_site_url) {
    throw new Error('Conflicting WordPress URLs for test location: ' + user.location_name);
  }
}
return [{ json: { audience, test_only: testOnly, locations: testOnly ? testLocations : roster.locations,
  doctors: testOnly ? roster.testUsers.map((user) => ({ name: user.name, email: user.email, location_code: locationByName.get(user.location_name).code })) : roster.doctors,
  excluded_location_count: roster.excludedLocations.length, excluded_doctor_count: roster.excludedDoctors.length } }];

const roster = $('Validate current roster').first().json;
if (roster.test_only !== true || roster.audience !== 'Test users only') throw new Error('Only Test User recipients can launch this workflow.');
const input = $input.first().json;
const raw = input['Test practice to use (select exactly one)'];
const selections = Array.isArray(raw) ? raw : raw ? [raw] : [];
if (selections.length !== 1) throw new Error('Select exactly one test practice.');
const byLabel = new Map(roster.locations.map((x) => [x.code + ' — ' + x.name, x]));
const location = byLabel.get(selections[0]);
if (!location) throw new Error('Unknown test practice selection.');
const doctors = roster.doctors.filter((x) => x.location_code === location.code);
if (!doctors.length) throw new Error('No test recipients at this practice.');
return [{ json: { locations: [location], doctors } }];

const available = $('Filter doctors by selected locations').first().json;
const roster = $('Validate current roster').first().json;
if (roster.test_only !== true || roster.audience !== 'Test users only') throw new Error('Real dentists are blocked from this test launcher.');
const input = $input.first().json;
const raw = input['Test recipients to invite (select one or more)'];
const selections = Array.isArray(raw) ? raw : raw ? [raw] : [];
if (!selections.length) throw new Error('Select at least one test recipient.');
const byLabel = new Map(available.doctors.map((x) => [x.name + ' (' + x.location_code + ') — ' + x.email, x]));
const doctors = selections.map((label) => {
  const doctor = byLabel.get(label);
  if (!doctor) throw new Error('Unknown test recipient: ' + label);
  return doctor;
});
if (new Set(doctors.map((x) => x.email)).size !== doctors.length) throw new Error('A test recipient was selected twice.');
if (available.locations.length !== 1) throw new Error('Exactly one test practice is required.');
const details = $('Start selection preview').first().json;
const campaignName = String(details.campaign_name ?? details['Campaign name'] ?? '').trim();
const month = String(details.campaign_month ?? details['Campaign month'] ?? '').slice(0,7);
const normalizeCentralAssetUrl = (value, number) => {
  const rawUrl = String(value ?? '').trim();
  if (!rawUrl) throw new Error('Topic ' + number + ' needs a featured image URL.');
  const match = rawUrl.match(/^https?:\/\/apexparent\.hostmanpowered\.com(\/wp-content\/uploads\/[^?#]+)(?:\?[^#]*)?(?:#.*)?$/i);
  if (!match) throw new Error('Topic ' + number + ' featured image must be an HTTP or HTTPS URL from the Apex Parent media library.');
  return 'https://apexparent.hostmanpowered.com' + match[1];
};
const topics = [1, 2, 3].map((number) => ({
  title: String(details['Topic ' + number] ?? '').trim(),
  featured_image_source_url: normalizeCentralAssetUrl(details['Topic ' + number + ' featured image central source URL'], number),
  featured_image_alt_text: String(details['Topic ' + number + ' featured image alt text'] ?? '').trim(),
  featured_image_source_type: String(details['Topic ' + number + ' featured image source type'] ?? '').trim(),
  featured_image_rights_reference: String(details['Topic ' + number + ' featured image rights or source reference'] ?? '').trim()
}));
if (!campaignName) throw new Error('Enter a campaign name.');
if (!/^\d{4}-\d{2}$/.test(month)) throw new Error('Choose a valid campaign month.');
for (let index = 0; index < topics.length; index++) {
  const topic = topics[index];
  const number = index + 1;
  if (!topic.title) throw new Error('Enter Topic ' + number + '.');
  if (topic.featured_image_alt_text.length < 8) throw new Error('Topic ' + number + ' needs useful featured image alt text.');
  if (!topic.featured_image_source_type) throw new Error('Choose the image source type for Topic ' + number + '.');
  if (!topic.featured_image_rights_reference) throw new Error('Enter the image rights or source reference for Topic ' + number + '.');
}
if (new Set(topics.map((topic) => topic.title.toLowerCase())).size !== 3) throw new Error('Enter three distinct topics.');
return [{ json: { test_only:true, campaign_name:campaignName, campaign_month:month, topics,
  location:available.locations[0], recipients:doctors, recipient_count:doctors.length,
  message:'Selection preview only. No invitations have been sent.' } }];

const confirmation = String($input.first().json['Type SEND TEST INVITATIONS to confirm'] ?? '').trim();
if (confirmation !== 'SEND TEST INVITATIONS') throw new Error('Type SEND TEST INVITATIONS exactly to launch.');
const preview = $('Preview selection without sending').first().json;
const roster = $('Validate current roster').first().json;
if (preview.test_only !== true || roster.test_only !== true || roster.audience !== 'Test users only') throw new Error('Dentist campaigns are disabled in this launcher.');
if (!preview.location || !Array.isArray(preview.recipients) || preview.recipients.length < 1 || preview.recipients.length > 10) throw new Error('Select one test practice and 1–10 test recipients.');
const wordpressUrl = String(preview.location.wordpress_site_url ?? '').replace(/\/+$/, '').toLowerCase();
if (wordpressUrl !== 'https://apexparent.hostmanpowered.com/test001') throw new Error('Only the verified TEST001 WordPress subsite is enabled.');
const allowed = new Map(roster.doctors.map(x => [x.email, x]));
for (const recipient of preview.recipients) {
  const source = allowed.get(recipient.email);
  if (!source || source.name !== recipient.name || source.location_code !== preview.location.code) throw new Error('Selected recipient is not a current Test User at TEST001.');
}
if (new Set(preview.recipients.map(x => x.email)).size !== preview.recipients.length) throw new Error('Duplicate test recipient.');
const campaignName = String(preview.campaign_name ?? '').trim();
const month = String(preview.campaign_month ?? '');
const topics = preview.topics;
if (!campaignName || !/^\d{4}-\d{2}$/.test(month) || !Array.isArray(topics) || topics.length !== 3 || topics.some((topic) => !topic.title || !/^https:\/\//i.test(topic.featured_image_source_url) || topic.featured_image_alt_text.length < 8 || !topic.featured_image_source_type || !topic.featured_image_rights_reference) || new Set(topics.map(x => String(x.title).toLowerCase())).size !== 3) throw new Error('Campaign details are incomplete.');
const slug = campaignName.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,48);
if (!slug) throw new Error('Campaign name needs letters or numbers.');
const campaignId = 'campaign_test_' + month.replace('-','') + '_' + slug;
const doctors = preview.recipients.map(x => ({doctor_id:'doctor_' + x.email.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,''),name:x.name,email:x.email.toLowerCase()}));
const payload = {test_only:true,practice_id:'practice_test_001',wordpress_site_url:wordpressUrl,campaign_id:campaignId,campaign_name:campaignName,campaign_month:month+'-01',topics,doctors};
return [{json:{payload_json:JSON.stringify(payload),campaign_id:campaignId,recipient_count:doctors.length,test_only:true}}];

parameters.sqlQuery:
DECLARE p JSON DEFAULT PARSE_JSON(@payload);
DECLARE v_campaign_id STRING DEFAULT JSON_VALUE(p, '$.campaign_id');
DECLARE v_practice_id STRING DEFAULT JSON_VALUE(p, '$.practice_id');
ASSERT JSON_VALUE(p, '$.test_only') = 'true' AS 'Only test campaigns can be launched here.';
ASSERT v_practice_id = 'practice_test_001' AS 'Only TEST001 is enabled.';
ASSERT JSON_VALUE(p, '$.wordpress_site_url') = 'https://apexparent.hostmanpowered.com/test001' AS 'Unexpected WordPress site.';
ASSERT ARRAY_LENGTH(JSON_QUERY_ARRAY(p, '$.doctors')) BETWEEN 1 AND 10 AS 'Select 1–10 test recipients.';
ASSERT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.practices` WHERE practice_id = v_practice_id AND active = TRUE AND UPPER(COALESCE(publisher_type,'')) = 'WORDPRESS' AND JSON_VALUE(publisher_config_reference, '$.wordpress_base_url') = 'https://apexparent.hostmanpowered.com/test001') AS 'TEST001 WordPress publishing configuration is missing.';
ASSERT NOT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.doctors` d JOIN UNNEST(JSON_QUERY_ARRAY(p, '$.doctors')) doctor ON LOWER(d.email) = LOWER(JSON_VALUE(doctor, '$.email')) WHERE COALESCE(d.practice_id, '') != v_practice_id) AS 'An existing doctor email belongs to a different practice.';
ASSERT NOT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.doctors` d JOIN UNNEST(JSON_QUERY_ARRAY(p, '$.doctors')) doctor ON LOWER(d.email) = LOWER(JSON_VALUE(doctor, '$.email')) WHERE d.doctor_id != JSON_VALUE(doctor, '$.doctor_id') AND COALESCE(d.practice_id, '') != v_practice_id) AS 'An existing doctor email has a different non-test profile ID.';
ASSERT NOT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.doctors` d JOIN UNNEST(JSON_QUERY_ARRAY(p, '$.doctors')) doctor ON d.doctor_id = JSON_VALUE(doctor, '$.doctor_id') WHERE COALESCE(d.practice_id, '') != v_practice_id) AS 'A selected test doctor ID belongs to another practice.';
ASSERT NOT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.campaigns` WHERE campaign_id = v_campaign_id) AS 'This campaign name and month have already been launched.';
ASSERT ARRAY_LENGTH(JSON_QUERY_ARRAY(p, '$.topics')) = 3 AS 'Exactly three topics are required.';
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_source_url STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_alt_text STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_source_type STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_rights_reference STRING;
BEGIN TRANSACTION;
INSERT INTO `apex-marketing-n8n.automated_article_creation.campaigns`
(campaign_id, campaign_name, campaign_month, status, doctor_review_days, require_marketing_approval, created_at, launched_at)
VALUES (v_campaign_id, JSON_VALUE(p, '$.campaign_name'), DATE(JSON_VALUE(p, '$.campaign_month')), 'LAUNCHED', 5, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP());
INSERT INTO `apex-marketing-n8n.automated_article_creation.campaign_topics`
(topic_id, campaign_id, topic_title, topic_description, interview_guidance,
  featured_image_source_url, featured_image_alt_text, featured_image_source_type,
  featured_image_rights_reference, topic_sort_order, active, created_at)
SELECT CONCAT(v_campaign_id, '_topic_', CAST(sort_order AS STRING)), v_campaign_id,
  JSON_VALUE(topic, '$.title'), JSON_VALUE(topic, '$.title'), NULL,
  JSON_VALUE(topic, '$.featured_image_source_url'), JSON_VALUE(topic, '$.featured_image_alt_text'),
  JSON_VALUE(topic, '$.featured_image_source_type'), JSON_VALUE(topic, '$.featured_image_rights_reference'),
  sort_order, TRUE, CURRENT_TIMESTAMP()
FROM UNNEST(JSON_QUERY_ARRAY(p, '$.topics')) AS topic WITH OFFSET AS zero_order
CROSS JOIN UNNEST([zero_order + 1]) AS sort_order;
MERGE `apex-marketing-n8n.automated_article_creation.doctors` T
USING (SELECT JSON_VALUE(doctor, '$.doctor_id') AS doctor_id, JSON_VALUE(doctor, '$.name') AS doctor_name, JSON_VALUE(doctor, '$.email') AS email
  FROM UNNEST(JSON_QUERY_ARRAY(p, '$.doctors')) AS doctor) S
ON T.doctor_id = S.doctor_id
WHEN MATCHED THEN UPDATE SET doctor_name = S.doctor_name, email = S.email, practice_id = v_practice_id, active = TRUE, updated_at = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN INSERT (doctor_id, doctor_name, email, practice_id, preferred_communication_channel, fallback_communication_channel, active, created_at, updated_at)
  VALUES (S.doctor_id, S.doctor_name, S.email, v_practice_id, 'email', 'email', TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP());
INSERT INTO `apex-marketing-n8n.automated_article_creation.campaign_doctors`
(campaign_id, doctor_id, status, invited_at, created_at, updated_at)
SELECT v_campaign_id, JSON_VALUE(doctor, '$.doctor_id'), 'READY', NULL, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()
FROM UNNEST(JSON_QUERY_ARRAY(p, '$.doctors')) AS doctor;
INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (GENERATE_UUID(), 'campaign', v_campaign_id, 'campaign.started', CURRENT_TIMESTAMP(), 'n8n:campaign-form', NULL,
  TO_JSON(STRUCT(ARRAY_LENGTH(JSON_QUERY_ARRAY(p, '$.topics')) AS topic_count, ARRAY_LENGTH(JSON_QUERY_ARRAY(p, '$.doctors')) AS doctor_count)));
COMMIT TRANSACTION;
SELECT v_campaign_id AS campaign_id, 'LAUNCHED' AS status, ARRAY_LENGTH(JSON_QUERY_ARRAY(p, '$.doctors')) AS doctor_count;
